-- Reviewed local database only. Supply existing synthetic owner/other-owner
-- and an owned ready main reference via native_media.fixture_reference JSON.
-- No provider upload/generation is called; all metadata writes roll back.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE native_media_fixture_results(name text PRIMARY KEY,passed boolean NOT NULL);
CREATE FUNCTION pg_temp.media_assert(p boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF p IS NOT TRUE THEN RAISE EXCEPTION 'FIXTURE_ASSERTION_FAILED: %',label;END IF;INSERT INTO native_media_fixture_results VALUES(label,true);END$$;
DO $$<<fixture>>DECLARE
 actor text:=current_setting('native_ai.fixture_owner',true);other_actor text:=current_setting('native_ai.fixture_other_owner',true);reference jsonb:=current_setting('native_media.fixture_reference',true)::jsonb;
 collection_id uuid;target_id uuid;draft_id uuid;entry_id uuid;copy_id uuid;media_id uuid:=gen_random_uuid();source jsonb;media jsonb;metadata jsonb;payload jsonb;request jsonb;result jsonb;entry public.pub_native_media_entries%ROWTYPE;before_assets bigint;before_wallet jsonb;after_wallet jsonb;rejected boolean;is_video boolean;
 entitlement uuid;account_id uuid;publish_target uuid:=gen_random_uuid();prepared_draft uuid;prepared_version integer;publish_batch uuid;attempt_id uuid;browser_target jsonb;attempt_snapshot jsonb;facts jsonb;provider_entry uuid;
 auth_id uuid:=gen_random_uuid();binding_id uuid:=gen_random_uuid();forged_asset uuid:=gen_random_uuid();intent_id uuid:=gen_random_uuid();op_id uuid:=gen_random_uuid();official_target jsonb;intent_payload jsonb;submit_request jsonb;operation_snapshot jsonb;bad_request jsonb;core_before bigint;plans_before bigint;
BEGIN
 IF actor IS NULL OR other_actor IS NULL OR actor=other_actor OR reference IS NULL THEN RAISE EXCEPTION 'EXPLICIT_SYNTHETIC_OWNERS_AND_READY_MAIN_REFERENCE_REQUIRED';END IF;
 PERFORM public.pub_assert_actor(actor);PERFORM public.pub_assert_actor(other_actor);source:=jsonb_build_object('kind','main_asset','reference',reference);PERFORM public.native_ai_assert_source(actor,source);
 SELECT count(*) INTO before_assets FROM public.pub3_assets;
 SELECT jsonb_build_object('credits',credits,'cash',cash_balance) INTO before_wallet FROM public.users WHERE id=actor;
 result:=public.mutate_publish_v2_atomic(actor,jsonb_build_object('action','save-collection','expectedRevision',0,'name','main media fixture','description','','archived',false));collection_id:=(result->'row'->>'id')::uuid;
 result:=public.mutate_publish_v2_atomic(actor,jsonb_build_object('action','save-collection','expectedRevision',0,'name','main media target','description','','archived',false));target_id:=(result->'row'->>'id')::uuid;
 is_video:=reference->>'kind'='video_task';
 media:=jsonb_build_object('id',media_id,'role',CASE WHEN is_video THEN 'video' ELSE 'image' END,'fileName',CASE WHEN is_video THEN 'fixture.mp4' ELSE 'fixture.png' END,'size',1,'type',CASE WHEN is_video THEN 'video/mp4' ELSE 'image/png' END,'lastModified',0,'source','main_asset','requiresReselection',false,'reference',reference);
 metadata:=jsonb_build_object('schemaVersion',2,'media',jsonb_build_array(jsonb_build_object('mediaId',media_id,'source',source)),'coverMediaId',NULL,'accountTypes','[]'::jsonb,'maxUseCountByAccountType','{}'::jsonb);
 payload:=jsonb_build_object('schemaVersion',2,'collectionId',collection_id,'contentType',CASE WHEN is_video THEN 'video' ELSE 'image' END,'title','main media fixture','body','','topics','[]'::jsonb,'media',jsonb_build_array(media),'targets','[]'::jsonb);
 request:=jsonb_build_object('action','save-native-draft','requestKey','media.fixture.save.'||media_id::text,'requestHash',repeat('a',64),'connectionId','fixture:metadata-only','save',jsonb_build_object('action','save-draft','base',jsonb_build_object('action','save-draft','expectedRevision',0,'draft',payload),'expectedMetadataRevision',0,'metadata',metadata),'mediaEntryRefs','[]'::jsonb);
 result:=public.mutate_native_core_atomic(actor,request);draft_id:=(result->'base'->'row'->>'id')::uuid;
 SELECT e.* INTO entry FROM public.pub_native_media_entries e JOIN public.pub_native_media_usage_refs u ON u.media_entry_id=e.id AND u.owner_id=e.owner_id WHERE u.owner_id=actor AND u.draft_id=fixture.draft_id AND u.draft_version=1 AND u.media_id=fixture.media_id;entry_id:=entry.id;
 PERFORM pg_temp.media_assert(entry.id IS NOT NULL AND entry.asset_id IS NULL AND entry.source_kind='main_asset' AND entry.main_reference=reference,'main reference has strict source identity and real usage link');
 PERFORM pg_temp.media_assert((SELECT count(*) FROM public.pub3_assets)=before_assets,'no fake provider asset is inserted');
 result:=public.mutate_native_core_atomic(actor,request);
 PERFORM pg_temp.media_assert(result->>'alreadyFulfilled'='true' AND (SELECT count(*) FROM public.pub_native_media_entries e WHERE e.owner_id=actor AND e.main_reference=reference AND e.collection_id=fixture.collection_id)=1,'V2 save replay does not duplicate media entries');
 rejected:=false;BEGIN PERFORM public.mutate_native_core_atomic(actor,jsonb_set(request,'{save,base,draft,title}','"changed"'));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='PUBLISH_IDEMPOTENCY_CONFLICT';END;PERFORM pg_temp.media_assert(rejected,'V2 save cannot replace idempotent input');
 result:=public.mutate_native_core_atomic(actor,jsonb_build_object('action','transfer-media','requestKey','media.fixture.copy.'||media_id::text,'requestHash',repeat('b',64),'connectionId','fixture:metadata-only','items',jsonb_build_array(jsonb_build_object('id',entry_id,'expectedRevision',1)),'targetCollectionId',target_id,'expectedTargetCollectionRevision',1,'mode','copy'));copy_id:=(result->'items'->0->>'id')::uuid;
 SELECT * INTO entry FROM public.pub_native_media_entries WHERE id=copy_id AND owner_id=actor;
 PERFORM pg_temp.media_assert(copy_id<>entry_id AND entry.is_copy AND entry.source_entry_id=entry_id AND entry.asset_id IS NULL AND entry.main_reference=reference,'clone has new entry ID and exact source');
 result:=public.mutate_native_core_atomic(actor,jsonb_build_object('action','transfer-media','requestKey','media.fixture.move.'||media_id::text,'requestHash',repeat('c',64),'connectionId','fixture:metadata-only','items',jsonb_build_array(jsonb_build_object('id',entry_id,'expectedRevision',1)),'targetCollectionId',target_id,'expectedTargetCollectionRevision',1,'mode','move'));
 SELECT * INTO entry FROM public.pub_native_media_entries WHERE id=entry_id AND owner_id=actor;
 PERFORM pg_temp.media_assert(entry.collection_id=target_id AND entry.revision=2 AND entry.main_reference=reference,'move preserves source and increments revision');
 PERFORM pg_temp.media_assert((SELECT u.media_entry_id FROM public.pub_native_media_usage_refs u WHERE u.owner_id=actor AND u.draft_id=fixture.draft_id AND u.draft_version=1 AND u.media_id=fixture.media_id)=entry_id,'existing usage attribution survives media move');
 -- Existing synthetic fixture entitlement only. These rows exercise provenance,
 -- not admission: no claim RPC, quota update, provider call or real publication.
 entitlement:=nullif(current_setting('native_media.fixture_entitlement',true),'')::uuid;
 IF entitlement IS NULL THEN SELECT id INTO entitlement FROM public.pub_entitlements WHERE user_id=actor ORDER BY created_at LIMIT 1;END IF;
 IF entitlement IS NULL OR NOT EXISTS(SELECT 1 FROM public.pub_entitlements WHERE id=entitlement AND user_id=actor) THEN RAISE EXCEPTION 'EXPLICIT_OWNED_SYNTHETIC_ENTITLEMENT_REQUIRED';END IF;
 result:=public.save_publish_account_atomic(actor,'xhs','media.fixture:'||media_id::text,'synthetic browser fixture',NULL);account_id:=(result->>'id')::uuid;
 browser_target:=jsonb_build_object('id',publish_target,'accountId',account_id,'platform','xhs','scheduledAt',NULL,'mediaIds',jsonb_build_array(media_id),'options','{}'::jsonb);
 request:=jsonb_build_object('action','prepare-publish','requestKey','media.fixture.prepare.'||media_id::text,'connectionId','fixture:metadata-only','plan',jsonb_build_object('requestKey','media.fixture.prepare.'||media_id::text,'planHash',repeat('e',64),'sourceDraftId',draft_id,'sourceDraftVersion',1,'groups',jsonb_build_array(jsonb_build_object('key',CASE WHEN is_video THEN 'video' ELSE 'image' END,'draft',jsonb_set(payload,'{targets}',jsonb_build_array(browser_target)),'metadata',metadata,'officialTargets','[]'::jsonb,'mediaEntryRefs',jsonb_build_array(jsonb_build_object('mediaId',media_id,'mediaEntryId',entry_id))))));
 -- Synthetic, uncommitted provider rows demonstrate that matching owner and
 -- local_media_id are insufficient evidence of a main-source upload bridge.
 INSERT INTO public.pub3_auth_sessions(id,owner_id,connection_id,platform,request_key) VALUES(auth_id,actor,'fixture:metadata-only','douyin','media.fixture.auth.'||media_id::text);
 INSERT INTO public.pub3_account_bindings(id,owner_id,connection_id,platform,provider_account_id,platform_uid,display_name,auth_session_id) VALUES(binding_id,actor,'fixture:metadata-only','douyin','synthetic.'||media_id::text,'synthetic.'||media_id::text,'synthetic bridge gate',auth_id);
 INSERT INTO public.pub3_assets(id,owner_id,connection_id,local_media_id,file_name,mime,size,sha256,provider_asset_id,public_url,metadata,state,request_key) VALUES(forged_asset,actor,'fixture:metadata-only',media_id,media->>'fileName',media->>'type',1,repeat('f',64),'synthetic.'||media_id::text,'https://example.invalid/synthetic/'||media_id::text,jsonb_build_object('duration',1),'ready','media.fixture.asset.'||media_id::text);
 official_target:=jsonb_build_object('id',gen_random_uuid(),'bindingId',binding_id,'bindingRevision',1,'mediaIds',jsonb_build_array(media_id),'assetIds',jsonb_build_array(forged_asset),'publishAt',NULL,'options',jsonb_build_object('short_title','fixture'));
 bad_request:=jsonb_set(jsonb_set(jsonb_set(request,'{requestKey}',to_jsonb('media.fixture.bridge.'||media_id::text)),'{plan,requestKey}',to_jsonb('media.fixture.bridge.'||media_id::text)),'{plan,groups,0,officialTargets}',jsonb_build_array(official_target));
 SELECT count(*) INTO core_before FROM public.pub_native_core_requests WHERE owner_id=actor;SELECT count(*) INTO plans_before FROM public.pub_native_publish_plans WHERE owner_id=actor;
 rejected:=false;BEGIN PERFORM public.mutate_native_auxiliary_atomic(actor,bad_request);EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_MAIN_BRIDGE_REQUIRED';END;
 PERFORM pg_temp.media_assert(rejected AND (SELECT count(*) FROM public.pub_native_core_requests WHERE owner_id=actor)=core_before AND (SELECT count(*) FROM public.pub_native_publish_plans WHERE owner_id=actor)=plans_before,'main V2 official prepare rejects same-owner matching-media provider asset before receipts');
 intent_payload:=(official_target-'id')||jsonb_build_object('draftId',draft_id,'draftVersion',1);
 rejected:=false;BEGIN PERFORM public.mutate_publish_v3_atomic(actor,jsonb_build_object('action','save-intent','connectionId','fixture:metadata-only','expectedRevision',0,'payload',intent_payload));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_MAIN_BRIDGE_REQUIRED';END;PERFORM pg_temp.media_assert(rejected,'direct V3 intent cannot bypass main bridge gate');
 rejected:=false;BEGIN PERFORM public.mutate_publish_v3_atomic(actor,jsonb_build_object('action','save-intent','connectionId','fixture:metadata-only','expectedRevision',0,'payload',jsonb_set(intent_payload,'{mediaIds}',jsonb_build_array(gen_random_uuid()))||jsonb_build_object('coverMediaId',media_id)));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_MAIN_BRIDGE_REQUIRED';END;PERFORM pg_temp.media_assert(rejected,'main reference used only as official cover still requires bridge');
 -- Simulate a pre-migration intent; new submit and unconsumed grants must gate
 -- it too. Existing issued replay remains governed by the exact legacy key/hash.
 INSERT INTO public.pub3_intents(id,owner_id,draft_id,draft_version,binding_id,binding_revision,payload) VALUES(intent_id,actor,draft_id,1,binding_id,1,intent_payload);
 SELECT jsonb_build_object('draft',payload,'intent',intent_payload,'binding',jsonb_build_object('id',b.id,'revision',b.revision,'providerAccountId',b.provider_account_id,'platformUid',b.platform_uid),'assets',jsonb_build_array(jsonb_build_object('id',a.id,'mediaId',a.local_media_id,'size',a.size,'mime',a.mime,'sha256',a.sha256,'providerAssetId',a.provider_asset_id,'publicUrl',a.public_url,'metadata',a.metadata)),'request',jsonb_build_object('flowId','synthetic.'||media_id::text,'publishAt',to_char(now(),'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'content',jsonb_build_object('title',payload->>'title','body','','media',jsonb_build_array(jsonb_build_object('url',a.public_url))),'items',jsonb_build_array(jsonb_build_object('platform','douyin','accountId',b.provider_account_id,'option',intent_payload->'options')))) INTO operation_snapshot FROM public.pub3_account_bindings b JOIN public.pub3_assets a ON a.id=forged_asset AND a.owner_id=b.owner_id AND a.connection_id=b.connection_id WHERE b.id=binding_id AND b.owner_id=actor;
 submit_request:=jsonb_build_object('action','submit','connectionId','fixture:metadata-only','operationId',op_id,'intentId',intent_id,'intentRevision',1,'entitlementId',entitlement,'flowId','synthetic.'||media_id::text,'requestKey','media.fixture.submit.'||media_id::text,'requestHash',repeat('d',64),'snapshot',operation_snapshot,'providerRequestHash',repeat('c',64));
 rejected:=false;BEGIN PERFORM public.mutate_publish_v3_atomic(actor,submit_request);EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_MAIN_BRIDGE_REQUIRED';END;PERFORM pg_temp.media_assert(rejected,'old unissued intent cannot submit native main reference without bridge');
 INSERT INTO public.pub3_operations(id,owner_id,kind,subject_id,connection_id,request_key,request_hash,snapshot,snapshot_hash,provider_request_hash,grant_kind,grant_subject,intent_revision) VALUES(op_id,actor,'publish',intent_id,'fixture:metadata-only',submit_request->>'requestKey',repeat('d',64),operation_snapshot,encode(sha256(convert_to(operation_snapshot::text,'UTF8')),'hex'),repeat('c',64),'create_flow','synthetic.'||media_id::text,1);
 rejected:=false;BEGIN PERFORM public.mutate_publish_v3_atomic(actor,jsonb_build_object('action','dispatch','connectionId','fixture:metadata-only','operationId',op_id));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_MAIN_BRIDGE_REQUIRED';END;PERFORM pg_temp.media_assert(rejected AND (SELECT dispatch_state='ready' AND NOT grant_used FROM public.pub3_operations WHERE id=op_id),'ready native main operation cannot dispatch without bridge');
 UPDATE public.pub3_operations SET dispatch_state='dispatching',revision=revision+1 WHERE id=op_id AND owner_id=actor;
 rejected:=false;BEGIN PERFORM public.mutate_publish_v3_atomic(actor,jsonb_build_object('action','consume-grant','connectionId','fixture:metadata-only','operationId',op_id,'grantKind','create_flow','grantSubject','synthetic.'||media_id::text,'providerRequestHash',repeat('c',64)));EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_MAIN_BRIDGE_REQUIRED';END;PERFORM pg_temp.media_assert(rejected AND (SELECT NOT grant_used FROM public.pub3_operations WHERE id=op_id),'unconsumed native main operation grant stays blocked');
 UPDATE public.pub3_operations SET grant_used=true,revision=revision+1 WHERE id=op_id AND owner_id=actor;
 result:=public.mutate_publish_v3_atomic(actor,submit_request);PERFORM pg_temp.media_assert(result->>'alreadyFulfilled'='true' AND result->'operation'->>'id'=op_id::text,'already-issued original operation exact-key replay remains readable');
 result:=public.mutate_publish_v3_atomic(actor,jsonb_build_object('action','record-operation','connectionId','fixture:metadata-only','operationId',op_id,'expectedRevision',3,'outcome','unknown'));PERFORM pg_temp.media_assert(result->'operation'->>'id'=op_id::text,'already-issued original operation observation remains permitted');
 result:=public.mutate_native_auxiliary_atomic(actor,request);prepared_draft:=(result->'groups'->0->'draft'->>'id')::uuid;prepared_version:=(result->'groups'->0->'draft'->>'revision')::integer;publish_batch:=(result->'groups'->0->'batch'->>'id')::uuid;
 PERFORM pg_temp.media_assert(EXISTS(SELECT 1 FROM public.pub_native_media_usage_refs u WHERE u.owner_id=actor AND u.draft_id=prepared_draft AND u.draft_version=prepared_version AND u.media_entry_id=entry_id),'browser prepare preserves exact main source provenance');
 SELECT jsonb_build_object('draft',result->'groups'->0->'draft'->'payload','draftId',prepared_draft,'draftVersion',prepared_version,'target',browser_target,'account',b.account_snapshots->0,'transport','browser_plugin','localSchedule',NULL) INTO attempt_snapshot FROM public.pub2_batches b WHERE b.user_id=actor AND b.id=publish_batch;
 INSERT INTO public.pub2_attempts(user_id,batch_id,target_id,entitlement_id,platform,snapshot,snapshot_hash,request_key,fingerprint) VALUES(actor,publish_batch,publish_target,entitlement,'xhs',attempt_snapshot,repeat('a',64),'media.fixture.report.'||media_id::text,repeat('b',64)) RETURNING id INTO attempt_id;
 INSERT INTO public.pub2_attempt_events(user_id,attempt_id,kind,request_key,payload,source) VALUES(actor,attempt_id,'browser_report','media.fixture.event.'||media_id::text,'{"success":true}'::jsonb,'browser_reported');
 result:=public.mutate_publish_v2_atomic(actor,jsonb_build_object('action','create-batch','draftId',prepared_draft,'draftVersion',prepared_version,'targetIds',jsonb_build_array(publish_target),'idempotencyKey','media.fixture.second-batch.'||media_id::text));publish_batch:=(result->'row'->>'id')::uuid;
 INSERT INTO public.pub2_attempts(user_id,batch_id,target_id,entitlement_id,platform,snapshot,snapshot_hash,request_key,fingerprint) VALUES(actor,publish_batch,publish_target,entitlement,'xhs',attempt_snapshot,repeat('c',64),'media.fixture.unknown.'||media_id::text,repeat('d',64));
 facts:=public.native_core_media_usage_facts(actor,entry_id);
 PERFORM pg_temp.media_assert(facts->>'browserReportedUses'='1' AND facts->>'unknownUses'='2' AND facts->'confirmedUses'='null'::jsonb AND facts->>'nativeUsageAttribution'='source_attribution_incomplete','main V2 browser reports stay separate and unbridged official receipt stays unknown');
 provider_entry:=nullif(current_setting('native_media.fixture_provider_entry',true),'')::uuid;
 IF provider_entry IS NULL THEN SELECT e.id INTO provider_entry FROM public.pub_native_media_entries e WHERE e.owner_id=actor AND e.source_kind='provider_asset' AND NOT EXISTS(SELECT 1 FROM public.pub_native_media_usage_refs u JOIN public.pub_native_draft_meta m ON m.owner_id=u.owner_id AND m.draft_id=u.draft_id AND m.draft_version=u.draft_version WHERE u.media_entry_id=e.id AND m.payload->'schemaVersion'='2'::jsonb) ORDER BY e.created_at LIMIT 1;END IF;
 IF provider_entry IS NULL THEN RAISE EXCEPTION 'EXPLICIT_OWNED_V1_PROVIDER_ENTRY_REQUIRED';END IF;
 PERFORM pg_temp.media_assert(public.native_core_media_usage_facts(actor,provider_entry)=public.native_core_media_usage_facts_v1(actor,provider_entry),'V1 provider usage retains exact original result');
 rejected:=false;BEGIN UPDATE public.pub_native_media_entries SET main_reference=jsonb_build_object('kind','image_record','id','forged') WHERE id=entry_id AND owner_id=actor;EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='NATIVE_MEDIA_SOURCE_IMMUTABLE';END;PERFORM pg_temp.media_assert(rejected,'source identity cannot be replaced after insert');
 rejected:=false;BEGIN INSERT INTO public.pub_native_media_entries(owner_id,asset_id,source_kind,main_reference,collection_id) VALUES(actor,NULL,'main_asset',NULL,collection_id);EXCEPTION WHEN check_violation THEN rejected:=true;END;PERFORM pg_temp.media_assert(rejected,'XOR rejects missing main source even under SQL NULL semantics');
 rejected:=false;BEGIN PERFORM public.native_assert_draft_metadata(metadata,payload,other_actor,'fixture:metadata-only');EXCEPTION WHEN OTHERS THEN rejected:=SQLERRM='PUBLISH_V2_ASSET_UNAVAILABLE';END;PERFORM pg_temp.media_assert(rejected,'main ledger source cannot cross members');
 result:=public.mutate_native_core_atomic(actor,jsonb_build_object('action','archive-media','requestKey','media.fixture.archive.'||media_id::text,'requestHash',repeat('d',64),'connectionId','fixture:metadata-only','items',jsonb_build_array(jsonb_build_object('id',copy_id,'expectedRevision',1))));
 PERFORM pg_temp.media_assert((SELECT archived FROM public.pub_native_media_entries WHERE id=copy_id AND owner_id=actor),'legacy archive action still accepts main entries');
 SELECT jsonb_build_object('credits',credits,'cash',cash_balance) INTO after_wallet FROM public.users WHERE id=actor;PERFORM pg_temp.media_assert(before_wallet=after_wallet,'media metadata operations do not change wallet');
END$$;
SELECT name,passed FROM native_media_fixture_results ORDER BY name;
ROLLBACK;
